-- Catalogue de bugs (31/10, preview validée par Rushi) : les bugs connus, reconnus par le launcher
-- chez le joueur et publiés sur /aide/bugs. Migration ADDITIVE : deux nouvelles tables préfixées et
-- les 12 premières fiches ; rien d'existant n'est modifié.

CREATE TABLE IF NOT EXISTS "bugCatalogEntry" (
  "id"          TEXT PRIMARY KEY,
  "slug"        TEXT NOT NULL UNIQUE,
  -- auto (corrigé tout seul), consent (réparation proposée), manual (à la main), analyse (jamais montré aux joueurs)
  "status"      TEXT NOT NULL DEFAULT 'analyse',
  -- player ou internal (équipe seulement : ni launcher ni page publique)
  "visibility"  TEXT NOT NULL DEFAULT 'player',
  "hasGuide"    INTEGER NOT NULL DEFAULT 0,
  "notify"      INTEGER NOT NULL DEFAULT 1,
  "published"   INTEGER NOT NULL DEFAULT 0,
  -- mods, curseforge, crash, launcher, dev
  "category"    TEXT NOT NULL DEFAULT 'crash',
  "titleFr"     TEXT NOT NULL DEFAULT '',
  "titleEn"     TEXT NOT NULL DEFAULT '',
  "symptomFr"   TEXT NOT NULL DEFAULT '',
  "symptomEn"   TEXT NOT NULL DEFAULT '',
  "causeFr"     TEXT NOT NULL DEFAULT '',
  "causeEn"     TEXT NOT NULL DEFAULT '',
  -- Liste fixe : none, ignore, loader, remove, replace, update, redownload, cache
  "fixAction"   TEXT NOT NULL DEFAULT 'none',
  "fixArg"      TEXT NOT NULL DEFAULT '',
  "fixTextFr"   TEXT NOT NULL DEFAULT '',
  "fixTextEn"   TEXT NOT NULL DEFAULT '',
  -- Tableaux JSON de phrases
  "stepsFr"     TEXT NOT NULL DEFAULT '[]',
  "stepsEn"     TEXT NOT NULL DEFAULT '[]',
  -- log, crash ou launcher
  "matchWhere"  TEXT NOT NULL DEFAULT 'log',
  -- Texte exact cherché, sans tenir compte des majuscules ; plusieurs variantes séparées par « || »
  "matchText"   TEXT NOT NULL DEFAULT '',
  "matchMc"     TEXT NOT NULL DEFAULT '',
  "matchLoader" TEXT NOT NULL DEFAULT '',
  "fixedIn"     TEXT NOT NULL DEFAULT '',
  "logSample"   TEXT NOT NULL DEFAULT '',
  "createdAt"   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  "updatedAt"   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- Seulement des compteurs par fiche et par jour : aucune donnée de joueur.
CREATE TABLE IF NOT EXISTS "bugCatalogStat" (
  "entryId"  TEXT NOT NULL REFERENCES "bugCatalogEntry"("id") ON DELETE CASCADE,
  "day"      TEXT NOT NULL,
  "seen"     INTEGER NOT NULL DEFAULT 0,
  "repaired" INTEGER NOT NULL DEFAULT 0,
  "refused"  INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY ("entryId", "day")
);

INSERT OR IGNORE INTO "bugCatalogEntry" ("id", "slug", "status", "visibility", "hasGuide", "notify", "published", "category", "titleFr", "titleEn", "symptomFr", "symptomEn", "causeFr", "causeEn", "fixAction", "fixArg", "fixTextFr", "fixTextEn", "stepsFr", "stepsEn", "matchWhere", "matchText", "matchMc", "matchLoader", "fixedIn", "logSample", "createdAt", "updatedAt") VALUES ('bug-1', 'fausse-alerte-creativecore', 'auto', 'player', 0, 0, 1, 'mods', 'Fausse alerte « EnhancedVisuals demande CreativeCore 2.0.0 »', 'False alert “EnhancedVisuals needs CreativeCore 2.0.0”', 'Dans « Corriger le pack » d''un pack Forge 1.12.2 (RLCraft…), le launcher disait qu''EnhancedVisuals a besoin de CreativeCore 2.0.0, une version qui n''existe pas en 1.12.2.', 'In “Fix the pack” for a Forge 1.12.2 pack (RLCraft…), the launcher said EnhancedVisuals needs CreativeCore 2.0.0, a version that does not exist for 1.12.2.', 'Le fichier d''EnhancedVisuals pour 1.12.2 contient par erreur un vieux mods.toml. Forge l''ignore, mais le launcher le lisait.', 'The 1.12.2 EnhancedVisuals file contains an old mods.toml by mistake. Forge ignores it, but the launcher was reading it.', 'ignore', '', 'Le launcher ne lit plus ce fichier pour Forge avant 1.13 : l''alerte ne s''affiche plus.', 'The launcher no longer reads that file for Forge before 1.13: the alert is gone.', '[]', '[]', 'launcher', 'creativecore [2.0.0,)', '< 1.13', 'forge', '0.4.1', '[Pack check] enhancedvisuals: META-INF/mods.toml -> creativecore [2.0.0,)', '2026-10-31T23:00:00.000Z', '2026-10-31T23:00:00.000Z');
INSERT OR IGNORE INTO "bugCatalogEntry" ("id", "slug", "status", "visibility", "hasGuide", "notify", "published", "category", "titleFr", "titleEn", "symptomFr", "symptomEn", "causeFr", "causeEn", "fixAction", "fixArg", "fixTextFr", "fixTextEn", "stepsFr", "stepsEn", "matchWhere", "matchText", "matchMc", "matchLoader", "fixedIn", "logSample", "createdAt", "updatedAt") VALUES ('bug-2', 'curseforge-mauvaise-page', 'auto', 'player', 0, 0, 1, 'curseforge', '« Ouvrir la page » ouvrait l''ancienne version d''un mod CurseForge', '“Open the page” opened the old version of a CurseForge mod', 'Pour un mod CurseForge à mettre à jour, le bouton ouvrait la page de l''ancien fichier, et le bon fichier téléchargé n''était jamais accepté.', 'For a CurseForge mod that needed an update, the button opened the old file''s page, and the right file was never accepted.', 'Le launcher attendait le fichier déjà installé au lieu de la version compatible.', 'The launcher was waiting for the installed file instead of the compatible version.', 'ignore', '', 'Le launcher cherche la bonne version (Minecraft + chargeur), ouvre la page exacte de ce fichier et attend ce fichier-là.', 'The launcher finds the right version (Minecraft + loader), opens that exact file''s page and waits for that file.', '[]', '[]', 'launcher', 'cf_wrong_file', '', '', '0.4.1', '', '2026-10-31T23:00:00.000Z', '2026-10-31T23:00:00.000Z');
INSERT OR IGNORE INTO "bugCatalogEntry" ("id", "slug", "status", "visibility", "hasGuide", "notify", "published", "category", "titleFr", "titleEn", "symptomFr", "symptomEn", "causeFr", "causeEn", "fixAction", "fixArg", "fixTextFr", "fixTextEn", "stepsFr", "stepsEn", "matchWhere", "matchText", "matchMc", "matchLoader", "fixedIn", "logSample", "createdAt", "updatedAt") VALUES ('bug-3', 'taille-de-fichier-fausse', 'auto', 'player', 0, 1, 1, 'mods', '« Taille reçue 122778 au lieu de 122777 » à l''installation', '“Received size 122778 instead of 122777” during install', 'L''installation d''un pack Modrinth (Better MC…) s''arrêtait sur un mod (Controlling, Structory…) à cause d''un octet de différence.', 'Installing a Modrinth pack (Better MC…) stopped on a mod (Controlling, Structory…) because of a one-byte difference.', 'L''index du pack annonce une mauvaise taille pour certains mods, alors que l''empreinte du fichier est juste.', 'The pack index lists a wrong size for some mods, while the file fingerprint is right.', 'ignore', '', 'L''empreinte du fichier fait foi ; la taille ne sert que si l''empreinte manque.', 'The file fingerprint wins; the size is only used when there is no fingerprint.', '[]', '[]', 'launcher', 'size_mismatch', '', '', '0.4.1', 'taille reçue 122778 au lieu de 122777', '2026-10-31T23:00:00.000Z', '2026-10-31T23:00:00.000Z');
INSERT OR IGNORE INTO "bugCatalogEntry" ("id", "slug", "status", "visibility", "hasGuide", "notify", "published", "category", "titleFr", "titleEn", "symptomFr", "symptomEn", "causeFr", "causeEn", "fixAction", "fixArg", "fixTextFr", "fixTextEn", "stepsFr", "stepsEn", "matchWhere", "matchText", "matchMc", "matchLoader", "fixedIn", "logSample", "createdAt", "updatedAt") VALUES ('bug-4', 'sodium-extra-fabric-0-20-1', 'consent', 'player', 0, 1, 1, 'crash', 'Le jeu se ferme au démarrage : Sodium Extra demande Fabric Loader 0.20.1', 'The game closes at startup: Sodium Extra needs Fabric Loader 0.20.1', 'Minecraft 1.21.11 s''arrête tout de suite avec « Incompatible mods found! » : Sodium Extra 0.9.5 a besoin de Fabric Loader 0.20.1 ou plus, le pack est en 0.19.5.', 'Minecraft 1.21.11 stops right away with “Incompatible mods found!”: Sodium Extra 0.9.5 needs Fabric Loader 0.20.1 or newer, the pack uses 0.19.5.', 'Le pack a été fait avec une version de Fabric trop ancienne pour Sodium Extra.', 'The pack was made with a Fabric version that is too old for Sodium Extra.', 'loader', '0.20.1', 'Passer Fabric Loader à la version 0.20.1 dans cette installation.', 'Move Fabric Loader to version 0.20.1 in this install.', '["Ouvre la page de ton installation dans Jouer.","Dans la liste des mods, coupe ou retire Sodium Extra.","Relance le jeu."]', '["Open your install''s page in Play.","In the mod list, turn off or remove Sodium Extra.","Start the game again."]', 'log', 'requires version 0.20.1 or later of fabricloader || requires version 0.20.1 or later of mod ''Fabric Loader''', '1.21.11', 'fabric', '', 'Incompatible mods found!
 - Mod ''Sodium Extra'' (sodium-extra) 0.9.5+mc1.21.11 requires version 0.20.1 or later of mod ''Fabric Loader'' (fabricloader), but only the wrong version is present: 0.19.5!', '2026-10-31T23:00:00.000Z', '2026-10-31T23:00:00.000Z');
INSERT OR IGNORE INTO "bugCatalogEntry" ("id", "slug", "status", "visibility", "hasGuide", "notify", "published", "category", "titleFr", "titleEn", "symptomFr", "symptomEn", "causeFr", "causeEn", "fixAction", "fixArg", "fixTextFr", "fixTextEn", "stepsFr", "stepsEn", "matchWhere", "matchText", "matchMc", "matchLoader", "fixedIn", "logSample", "createdAt", "updatedAt") VALUES ('bug-5', 'cps-plus-1-21-11', 'consent', 'player', 0, 1, 1, 'crash', 'Crash dès qu''on bouge la souris : CPS+ en 1.21.11', 'Crash as soon as the mouse moves: CPS+ on 1.21.11', 'Le jeu plante au premier mouvement de souris, le rapport de plantage parle d''un « mixin » de cps-plus.', 'The game crashes on the first mouse move, the crash report mentions a cps-plus “mixin”.', 'Le fichier CPS+ proposé pour 1.21.11 a en fait été fait pour 1.21.1.', 'The CPS+ file offered for 1.21.11 was actually made for 1.21.1.', 'replace', 'cps-plus → 52ZXihCZ', 'Remplacer CPS+ par CPS Counter de oneaura (même fonction, depuis Modrinth).', 'Replace CPS+ with oneaura''s CPS Counter (same feature, from Modrinth).', '["Ouvre la page de ton installation dans Jouer.","Retire CPS+ de la liste des mods.","Ajoute « CPS Counter » (oneaura) depuis Modrinth.","Relance le jeu."]', '["Open your install''s page in Play.","Remove CPS+ from the mod list.","Add “CPS Counter” (oneaura) from Modrinth.","Start the game again."]', 'crash', 'cps-plus || cpsplus', '1.21.11', 'fabric', '', 'org.spongepowered.asm.mixin.transformer.throwables.MixinTransformerError
  at cpsplus.mixin.MixinMouse (cps-plus-1.1.0.jar)', '2026-10-31T23:00:00.000Z', '2026-10-31T23:00:00.000Z');
INSERT OR IGNORE INTO "bugCatalogEntry" ("id", "slug", "status", "visibility", "hasGuide", "notify", "published", "category", "titleFr", "titleEn", "symptomFr", "symptomEn", "causeFr", "causeEn", "fixAction", "fixArg", "fixTextFr", "fixTextEn", "stepsFr", "stepsEn", "matchWhere", "matchText", "matchMc", "matchLoader", "fixedIn", "logSample", "createdAt", "updatedAt") VALUES ('bug-6', 'quilt-api-en-double', 'consent', 'player', 0, 1, 1, 'mods', '« Duplicate mandatory mod ids [fabric-api, quilted_fabric_api] »', '“Duplicate mandatory mod ids [fabric-api, quilted_fabric_api]”', 'Un pack Quilt refuse de démarrer : deux copies de l''API (Fabric API et Quilted Fabric API) sont dans le dossier mods.', 'A Quilt pack won''t start: two copies of the API (Fabric API and Quilted Fabric API) are in the mods folder.', 'Le pack contient les deux, alors qu''elles font la même chose.', 'The pack contains both, while they do the same thing.', 'remove', 'fabric-api', 'Retirer Fabric API : Quilted Fabric API la remplace.', 'Remove Fabric API: Quilted Fabric API replaces it.', '["Ouvre la page de ton installation dans Jouer.","Retire « Fabric API » (garde « Quilted Fabric API »).","Relance le jeu."]', '["Open your install''s page in Play.","Remove “Fabric API” (keep “Quilted Fabric API”).","Start the game again."]', 'log', 'Duplicate mandatory mod ids [fabric-api, quilted_fabric_api]', '', 'quilt', '', 'net.fabricmc.loader.impl.FormattedException: Duplicate mandatory mod ids [fabric-api, quilted_fabric_api]', '2026-10-31T23:00:00.000Z', '2026-10-31T23:00:00.000Z');
INSERT OR IGNORE INTO "bugCatalogEntry" ("id", "slug", "status", "visibility", "hasGuide", "notify", "published", "category", "titleFr", "titleEn", "symptomFr", "symptomEn", "causeFr", "causeEn", "fixAction", "fixArg", "fixTextFr", "fixTextEn", "stepsFr", "stepsEn", "matchWhere", "matchText", "matchMc", "matchLoader", "fixedIn", "logSample", "createdAt", "updatedAt") VALUES ('bug-7', 'fancymenu-drippy-neoforge', 'manual', 'player', 0, 1, 1, 'crash', 'Crash au menu avec FancyMenu 3.6.4 et Drippy Loading Screen', 'Crash at the menu with FancyMenu 3.6.4 and Drippy Loading Screen', 'Sur NeoForge 1.21.1, le jeu plante en arrivant au menu, le journal parle de « customizableScreens ».', 'On NeoForge 1.21.1, the game crashes when reaching the menu, the log mentions “customizableScreens”.', 'Un bug du mod FancyMenu, pas du launcher.', 'A bug in the FancyMenu mod, not in the launcher.', 'none', '', '', '', '["Ouvre la page de ton installation dans Jouer.","Si une version plus récente de FancyMenu existe, mets-la à jour.","Sinon, retire Drippy Loading Screen.","Relance le jeu. Si ça plante encore, copie les logs et écris-nous."]', '["Open your install''s page in Play.","If a newer FancyMenu exists, update it.","Otherwise, remove Drippy Loading Screen.","Start the game again. If it still crashes, copy the logs and write to us."]', 'log', 'customizableScreens', '1.21.1', 'neoforge', '', 'java.lang.NullPointerException at de.keksuccino.fancymenu.customization.customizableScreens', '2026-10-31T23:00:00.000Z', '2026-10-31T23:00:00.000Z');
INSERT OR IGNORE INTO "bugCatalogEntry" ("id", "slug", "status", "visibility", "hasGuide", "notify", "published", "category", "titleFr", "titleEn", "symptomFr", "symptomEn", "causeFr", "causeEn", "fixAction", "fixArg", "fixTextFr", "fixTextEn", "stepsFr", "stepsEn", "matchWhere", "matchText", "matchMc", "matchLoader", "fixedIn", "logSample", "createdAt", "updatedAt") VALUES ('bug-8', 'mods-curseforge-a-la-main', 'manual', 'player', 1, 1, 1, 'curseforge', 'Mods CurseForge à télécharger à la main', 'CurseForge mods to download by hand', 'À l''import d''un pack CurseForge, une fenêtre liste des mods que le launcher n''a pas le droit de télécharger tout seul.', 'When importing a CurseForge pack, a window lists mods the launcher is not allowed to download on its own.', 'Certains auteurs interdisent le téléchargement de leurs mods par un autre launcher que CurseForge. Omniscient respecte leur choix.', 'Some authors forbid other launchers than CurseForge from downloading their mods. Omniscient respects their choice.', 'none', '', '', '', '["Clique « Ouvrir la page » à côté du mod : la page du bon fichier s''ouvre.","Sur cette page, clique le bouton Download qui est SOUS le nom du fichier (pas celui du haut, qui donne la dernière version).","Laisse le fichier dans ton dossier Téléchargements.","Reviens au launcher et clique « Réessayer » : il trouve le fichier, le vérifie et le range tout seul.","Si une ligne rouge « Mauvaise version » apparaît, refais l''étape 2 avec l''autre bouton."]', '["Click “Open the page” next to the mod: the right file''s page opens.","On that page, click the Download button that is UNDER the file name (not the top one, which gives the latest version).","Leave the file in your Downloads folder.","Come back to the launcher and click “Retry”: it finds the file, checks it and puts it in place.","If a red “Wrong version” line shows up, redo step 2 with the other button."]', 'launcher', 'manual_download_required', '', '', '', '', '2026-10-31T23:00:00.000Z', '2026-10-31T23:00:00.000Z');
INSERT OR IGNORE INTO "bugCatalogEntry" ("id", "slug", "status", "visibility", "hasGuide", "notify", "published", "category", "titleFr", "titleEn", "symptomFr", "symptomEn", "causeFr", "causeEn", "fixAction", "fixArg", "fixTextFr", "fixTextEn", "stepsFr", "stepsEn", "matchWhere", "matchText", "matchMc", "matchLoader", "fixedIn", "logSample", "createdAt", "updatedAt") VALUES ('bug-9', 'crash-26-3-sodium-iris', 'analyse', 'player', 0, 1, 0, 'crash', 'Plantage Java de Minecraft 26.3 avec Sodium 0.9.3 (bêta) et Iris', 'Java crash on Minecraft 26.3 with Sodium 0.9.3 (beta) and Iris', 'Le jeu se ferme pendant le chargement, sans rapport de plantage Minecraft.', 'The game closes while loading, with no Minecraft crash report.', 'En cours d''analyse : il manque le fichier hs_err de Java.', 'Being analysed: the Java hs_err file is missing.', 'none', '', '', '', '["En attendant, joue la version 1.21.11 du même pack si elle existe."]', '["Meanwhile, play the 1.21.11 version of the same pack if there is one."]', 'log', 'EXCEPTION_ACCESS_VIOLATION', '26.3', '', '', '# A fatal error has been detected by the Java Runtime Environment:
#  EXCEPTION_ACCESS_VIOLATION (0xc0000005)', '2026-10-31T23:00:00.000Z', '2026-10-31T23:00:00.000Z');
INSERT OR IGNORE INTO "bugCatalogEntry" ("id", "slug", "status", "visibility", "hasGuide", "notify", "published", "category", "titleFr", "titleEn", "symptomFr", "symptomEn", "causeFr", "causeEn", "fixAction", "fixArg", "fixTextFr", "fixTextEn", "stepsFr", "stepsEn", "matchWhere", "matchText", "matchMc", "matchLoader", "fixedIn", "logSample", "createdAt", "updatedAt") VALUES ('bug-10', 'dev-maketesttoken-500', 'manual', 'internal', 0, 1, 1, 'dev', 'Erreur 500 « makeTestToken » sur le site en local', '500 error “makeTestToken” on the local site', '« Tester dans le launcher » dans l''admin renvoie une erreur 500 qui cite makeTestToken.', '“Test in the launcher” in the admin returns a 500 error mentioning makeTestToken.', 'Le cache de Next.js (dossier site\.next) garde une ancienne version du code.', 'The Next.js cache (site\.next folder) keeps an old version of the code.', 'none', '', '', '', '["Arrête npm run dev (Ctrl+C).","Supprime le dossier site\\.next.","Relance npm run dev."]', '["Stop npm run dev (Ctrl+C).","Delete the site\\.next folder.","Run npm run dev again."]', 'launcher', 'makeTestToken', '', '', '', 'TypeError: makeTestToken is not a function', '2026-10-31T23:00:00.000Z', '2026-10-31T23:00:00.000Z');
INSERT OR IGNORE INTO "bugCatalogEntry" ("id", "slug", "status", "visibility", "hasGuide", "notify", "published", "category", "titleFr", "titleEn", "symptomFr", "symptomEn", "causeFr", "causeEn", "fixAction", "fixArg", "fixTextFr", "fixTextEn", "stepsFr", "stepsEn", "matchWhere", "matchText", "matchMc", "matchLoader", "fixedIn", "logSample", "createdAt", "updatedAt") VALUES ('bug-11', 'dev-laboratoire-au-demarrage', 'auto', 'internal', 0, 0, 1, 'dev', '« Pack Omniscient est coupé dans le Laboratoire » quand le launcher était fermé', '“Omniscient Pack is off in the Lab” when the launcher was closed', 'Un clic sur « Tester dans le launcher » ouvrait le launcher, qui refusait aussitôt le pack.', 'Clicking “Test in the launcher” opened the launcher, which refused the pack right away.', 'Au démarrage, le launcher n''avait pas encore lu le Laboratoire quand la demande arrivait.', 'At startup, the launcher had not read the Lab yet when the request came in.', 'ignore', '', 'Le launcher attend jusqu''à 30 s que le Laboratoire soit lu.', 'The launcher waits up to 30 s for the Lab to be read.', '[]', '[]', 'launcher', 'feature_off omniPack', '', '', '0.4.1', '', '2026-10-31T23:00:00.000Z', '2026-10-31T23:00:00.000Z');
INSERT OR IGNORE INTO "bugCatalogEntry" ("id", "slug", "status", "visibility", "hasGuide", "notify", "published", "category", "titleFr", "titleEn", "symptomFr", "symptomEn", "causeFr", "causeEn", "fixAction", "fixArg", "fixTextFr", "fixTextEn", "stepsFr", "stepsEn", "matchWhere", "matchText", "matchMc", "matchLoader", "fixedIn", "logSample", "createdAt", "updatedAt") VALUES ('bug-12', 'dev-boucle-hmr', 'manual', 'internal', 0, 1, 1, 'dev', 'Rafales de GET /admin ou /dashboard dans le terminal du site', 'Bursts of GET /admin or /dashboard in the site terminal', 'Le terminal de npm run dev affiche des centaines de GET de la même page sans qu''aucun fichier ne change, et le quota de la base fond.', 'The npm run dev terminal shows hundreds of GETs of the same page while no file changes, and the database quota melts.', 'Boucle interne de next dev après un rechargement raté. N''existe pas en production.', 'Internal next dev loop after a failed reload. Does not happen in production.', 'none', '', '', '', '["Appuie sur F5 dans l''onglet qui boucle, ou ferme-le.","Pendant qu''un fil écrit du code, ferme /admin, /dashboard et /manage."]', '["Press F5 in the looping tab, or close it.","While a thread writes code, close /admin, /dashboard and /manage."]', 'launcher', 'GET /dashboard', '', '', '', 'GET /dashboard?_rsc=1x9 200 in 41ms (x280)', '2026-10-31T23:00:00.000Z', '2026-10-31T23:00:00.000Z');
